    jsonb_build_object('key','bonga_npsha_ft', 'label','NPSH available on the suction side as surveyed', 'unit','ft', 'expected',53.10759493670886, 'tol',5e-07),
    jsonb_build_object('key','bonga_npsha_raised_ft', 'label','NPSH available with the suction drum padded to the proposed pressure', 'unit','ft', 'expected',130.88734177215187, 'tol',5e-07),
    jsonb_build_object('key','bonga_speed_flow_gpm', 'label','Flow of the solved duty carried to the proposed speed by the affinity laws', 'unit','gpm', 'expected',789.6981924270747, 'tol',0.0001),
    jsonb_build_object('key','bonga_speed_head_ft', 'label','Head of the solved duty carried to the proposed speed by the affinity laws', 'unit','ft', 'expected',119.05179482935601, 'tol',1e-05),
    jsonb_build_object('key','bonga_parallel_flow_gpm', 'label','Duty flow with both machines in parallel against the same station', 'unit','gpm', 'expected',1047.5409037376212, 'tol',0.0001)
  )
),
(
  'rotating', 'advanced', 'expert',
  'BONNY K-3101, a gas booster train from its exponent through to what the driver burns',
  'The exponent, the staging, the first stage and the driver',
  'BONNY K-3101, the gas booster train. It takes 34.0 MMscfd from 138.0 psia and 96.0 degF up to 1240.0 psia. The gas gravity is 0.673 and k is 1.272. The polytropic efficiency is 0.767 and the mechanical efficiency is 0.972. The maximum ratio per stage is 3.8 and the maximum discharge temperature is 285.0 degF. The intercoolers return the gas to 96.0 degF between stages. The driver has a heat rate of 7650 Btu per hp hr and burns a fuel of 968 Btu per scf. Report six values from the exponent, the staging, the first stage and the driver. Temperatures in degF, heads in ft lbf per lbm and power in hp to four decimals. The exponent ratio, the ratio per stage and the fuel rate in MMscfd to nine decimals.',
  jsonb_build_array(
