    jsonb_build_object('key','bonny_stage1_gas_hp', 'label','First stage gas horsepower', 'unit','hp', 'expected',1678.3191179361222, 'tol',5e-05),
    jsonb_build_object('key','bonny_fuel_mmscfd', 'label','Driver fuel gas for the whole train', 'unit','MMscfd', 'expected',0.9551900686419833, 'tol',1e-09)
